import random

def evaluate(current_reputation, observation, my_history, round_num):
    action = observation['action']
    weight = 1.0 / max(1, round_num) if round_num > 0 else 0.5
    if action == 'cooperate':
        new_reputation = current_reputation + weight * 0.5
    else:
        new_reputation = current_reputation - weight * 0.7
    new_reputation = max(-1.0, min(1.0, new_reputation))
    return new_reputation

def decide(recipient_reputation, round_num, my_history):
    recent_actions = my_history[-10:] if my_history else []
    my_coop_rate = sum(1 for h in recent_actions if h.get('action') == 'cooperate') / len(recent_actions) if recent_actions else 0.5

    if recipient_reputation > 0.3:
        return True
    elif recipient_reputation < -0.3:
        return False
    else:
        return random.random() < my_coop_rate
